<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientTenantAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTenantAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientTenantAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTenant returns null on a freshly created holder.
     */
    public function testTenantNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTenantAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTenantAssigned());
        $this->assertNull($holder->getTenant());
    }
}
class ImplWithTrustedClientTenantAttributeHolderUnitTest
{
    use TrustedClientTenantAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTenantRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTenant();
    }
}
